#!/usr/bin/env python3
"""As-machined STEP models of the lot that ran 2026-09-18.

1. roll today's control backup back to the lot date with the operation history (OPRT-HIS.TXT);
2. what the history cannot reach (it starts 09-24) is settled against the CMM reports of that lot:
   for each open question (which T6 was in the spindle, how MNF-0610 OP20 was loaded, any work
   offset moved) machine the part, measure it like the QC program does, compare, and fit work
   offset shifts from the positional residuals;
3. keep the one reading that reproduces every reported characteristic within CMM noise, export.

usage: models.py <cnc dir> <shop dir> <qc dir> <out dir>
"""
import glob
import sys

import cadquery as cq

import cmm
import history
import parts

LOT = "2026/09/18 23:59:59"
WCS = {"MNF-0610": 2, "BRG-1140": 3, "LVR-2205": 4}       # last setup's work offset (G55/G56/G57)
FIT_TOL = 0.01     # three serials, sigma ~1.5 um: anything real sits well inside this


def measured(qc):
    """average of the serials per characteristic; None where a report says not found"""
    acc = {}
    for path in sorted(glob.glob(f"{qc}/*.TXT")):
        part, res = cmm.read_report(path)
        for name, vals in res.items():
            acc.setdefault(part, {}).setdefault(name, []).append(vals)
    out = {}
    for part, chars in acc.items():
        out[part] = {}
        for name, runs in chars.items():
            if any(r is None for r in runs):
                out[part][name] = None
                continue
            out[part][name] = {ax: sum(r[ax] for r in runs) / len(runs) for ax in runs[0]}
    return out


def compare(part, solid, axis, meas):
    """residuals (measured - model) per characteristic axis; missing features count as huge"""
    model = cmm.inspect(part, parts.to_print(part, solid, axis))
    res = {}
    for name, m in meas.items():
        s = model.get(name)
        if (m is None) != (s is None):
            res[(name, "found")] = 99.0
            continue
        if m is None:
            continue
        for ax, v in m.items():
            res[(name, ax)] = v - s[ax]
    return res


def worst(res):
    return max(abs(v) for v in res.values()) if res else 0.0


def shift_of(res):
    xs = [v for (n, ax), v in res.items() if ax == "X"]
    ys = [v for (n, ax), v in res.items() if ax == "Y"]
    return (round(sum(xs) / len(xs), 3) if xs else 0.0, round(sum(ys) / len(ys), 3) if ys else 0.0)


def settle(part, state, old_t6, axis, meas):
    """machine, compare, and if the residuals are a common XY offset, move that work offset"""
    tools, lengths = parts.crib(old_t6)
    st = dict(state, work={k: list(v) for k, v in state["work"].items()},
              off={k: dict(v) for k, v in state["off"].items()})
    if old_t6:      # H6 was re-entered from the presetter on 09-22, so it held the old drill
        st["off"]["Hg"][6] = parts.OLD_T6[1]
    s = parts.build(part, st, tools, lengths, axis)
    res = compare(part, s, axis, meas)
    if worst(res) > FIT_TOL and all(v < 99 for v in res.values()):
        dx, dy = shift_of(res)
        st["work"][WCS[part]][0] += dx
        st["work"][WCS[part]][1] += dy
        s = parts.build(part, st, tools, lengths, axis)
        res = compare(part, s, axis, meas)
        print(f"  {part}: work offset P{WCS[part]} moved by X{dx:+.3f} Y{dy:+.3f}", flush=True)
    return s, res


def main():
    cnc, shop, qc, out = sys.argv[1:5]
    today = history.load_state(cnc)
    state, undone, edits = history.roll_back(today, f"{cnc}/OPRT-HIS.TXT", LOT)
    print(f"history reaches back to {history.earliest(cnc + '/OPRT-HIS.TXT')}; undid {len(undone)} changes")
    for stamp, what in undone:
        print("  ", stamp, what)
    used = {1140, 1141, 1610, 1611, 1620, 1621, 2205, 2206, 9010, 9011, 9020}
    if used & set(edits):
        raise SystemExit(f"programs {used & set(edits)} were edited after the lot: cannot reconstruct")
    meas = measured(qc)
    found = {}
    for old_t6 in (False, True):            # TOOL-LIST: T6 was swapped on 09-22
        found = {}
        for part in ("BRG-1140", "LVR-2205", "MNF-0610"):
            for axis in (("X", "Y") if part == "MNF-0610" else ("X",)):
                s, res = settle(part, state, old_t6, axis, meas[part])
                print(f"T6 {'old' if old_t6 else 'current'} {part} OP20 axis {axis}: worst residual {worst(res):.4f}",
                      flush=True)
                if worst(res) <= FIT_TOL:
                    found[part] = s
                    break
            if part not in found:
                break
        if len(found) == 3:
            break
    if len(found) != 3:
        raise SystemExit("no reading of the lot reproduces the CMM reports")
    for name, s in found.items():
        cq.exporters.export(cq.Workplane().add(s), f"{out}/{name}.step")
        print(name, round(s.Volume(), 4), len(s.Faces()), "faces")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""roll the control backup back to a past date using the operation history export (OPRT-HIS.TXT).
every logged data change after the cut-off is undone (new value -> old value), newest first."""
import copy
import re

import fanuc

WORK_NO = {"EXT": 0, "G54": 1, "G55": 2, "G56": 3, "G57": 4, "G58": 5, "G59": 6}


def _norm(v):
    v = v.lstrip("P")
    if re.fullmatch(r"[01]{8}", v):
        return v
    return float(v)


def load_state(cnc):
    return {"progs": fanuc.load_programs(f"{cnc}/ALL-PROG.TXT"),
            "params": fanuc.read_params(f"{cnc}/CNC-PARA.TXT"),
            "off": fanuc.read_offsets(f"{cnc}/TOOLOFST.TXT"),
            "work": fanuc.read_work(f"{cnc}/EXT_WKZ.TXT")}


def events(path):
    out = []
    for line in open(path):
        m = re.match(r"\d{5}\s+(\d{4}/\d\d/\d\d \d\d:\d\d:\d\d)\s+(.*\S)", line)
        if m:
            out.append((m.group(1), m.group(2)))
    return out


def earliest(path):
    return min(t for t, _ in events(path))


def roll_back(state, path, before):
    """state as it was at `before` ("YYYY/MM/DD HH:MM:SS"), as far as the history reaches.
    returns (state, list of undone changes, list of program edits that cannot be undone)"""
    st = copy.deepcopy(state)
    undone, edits = [], []
    for stamp, what in sorted(events(path), reverse=True):
        if stamp <= before:
            break
        m = re.match(r"(WEAR|GEOM) OFFSET \((H|D)\)\s+NO\.(\d+)\s+(-?[\d.]+)\s+->\s+(-?[\d.]+)", what)
        if m:
            key = ("H" if m.group(2) == "H" else "D") + ("w" if m.group(1) == "WEAR" else "g")
            no, old, new = int(m.group(3)), float(m.group(4)), float(m.group(5))
            if abs(st["off"][key].get(no, 0.0) - new) > 1e-9:
                raise ValueError(f"history does not chain at {stamp}: {what}")
            st["off"][key][no] = old
            undone.append((stamp, what))
            continue
        m = re.match(r"WORK OFFSET\s+(\w+)\s+([XYZ])\s+(-?[\d.]+)\s+->\s+(-?[\d.]+)", what)
        if m:
            no, ax = WORK_NO[m.group(1)], "XYZ".index(m.group(2))
            old, new = float(m.group(3)), float(m.group(4))
            if abs(st["work"][no][ax] - new) > 1e-9:
                raise ValueError(f"history does not chain at {stamp}: {what}")
            st["work"][no][ax] = old
            undone.append((stamp, what))
            continue
        m = re.match(r"PARAMETER\s+NO\.(\d+)\s+(\S+)\s+->\s+(\S+)", what)
        if m:
            no, old, new = int(m.group(1)), m.group(2), m.group(3)
            if _norm(st["params"].get(no, "")) != _norm(new):
                raise ValueError(f"history does not chain at {stamp}: {what}")
            st["params"][no] = "P" + old
            undone.append((stamp, what))
            continue
        m = re.match(r"PROGRAM EDIT\s+O(\d+)", what)
        if m:
            edits.append(int(m.group(1)))
    return st, undone, edits

#!/usr/bin/env python3
"""Forward model: one part machined on a given control state with a given tool crib and setup."""
import cadquery as cq

import cut
import fanuc

# /app/shop/TOOL-LIST.TXT (as of today)
TOOLS = {
    1: cut.Tool("flat", 50.0),
    2: cut.Tool("flat", 16.0),
    3: cut.Tool("flat", 10.0),
    4: cut.Tool("cone", 12.0, point=90.0),
    5: cut.Tool("cone", 6.8, point=118.0),
    6: cut.Tool("cone", 6.6, point=140.0),
    7: cut.Tool("flat", 12.0),
    8: cut.Tool("cone", 12.0, point=90.0, tip_flat=2.0),
    9: cut.Tool("bull", 8.0, corner=1.0),
    10: cut.Tool("flat", 11.0),
}
LENGTH = {1: 98.412, 2: 110.250, 3: 102.775, 4: 95.300, 5: 124.640, 6: 121.115, 7: 108.880,
          8: 101.505, 9: 99.730, 10: 96.210}
# the T6 that came out on 09-22 (TOOL-LIST note)
OLD_T6 = (cut.Tool("cone", 6.8, point=118.0), 126.880)

# /app/shop/VISE-SETUP.TXT
STOP_X, JAW_Y, PAR_Z = -612.0, -208.0, -455.0


def block(dx, dy, dz):
    """stock square in the vise: left end on the stop, back on the fixed jaw, bottom on parallels"""
    return cq.Solid.makeBox(dx, dy, dz, cq.Vector(STOP_X, JAW_Y - dy, PAR_Z))


def _walls(part, contact):
    bb = part.BoundingBox()
    slab = cq.Solid.makeBox(bb.xlen + 20, bb.ylen + 20, contact + 5,
                            cq.Vector(bb.xmin - 10, bb.ymin - 10, bb.zmax - contact))
    return bb, part.intersect(slab).BoundingBox()


def turn_over(part, axis="X", contact=15.0):
    """OP20 load: finished top down on the parallels, jaw and stop on the profiled walls within
    `contact` of the top. axis X (setup sheet): OP10 front face to the jaw, left end to the stop.
    axis Y: OP10 back face stays on the jaw, OP10 right end goes to the stop."""
    bb, wall = _walls(part, contact)
    if axis == "X":     # (x, y, z) -> (x, -y, -z)
        turned = part.rotate(cq.Vector(0, 0, 0), cq.Vector(1, 0, 0), 180)
        return turned.translate(cq.Vector(STOP_X - wall.xmin, JAW_Y + wall.ymin, PAR_Z + bb.zmax))
    turned = part.rotate(cq.Vector(0, 0, 0), cq.Vector(0, 1, 0), 180)    # (x, y, z) -> (-x, y, -z)
    return turned.translate(cq.Vector(STOP_X + wall.xmax, JAW_Y - wall.ymax, PAR_Z + bb.zmax))


def to_print(part, solid, axis="X"):
    """put a finished part in print orientation (OP10 top up, OP10 front toward -Y)"""
    if part != "MNF-0610":
        return solid
    if axis == "X":
        return solid.rotate(cq.Vector(0, 0, 0), cq.Vector(1, 0, 0), 180)
    return solid.rotate(cq.Vector(0, 0, 0), cq.Vector(0, 1, 0), 180)


def machine(stock, moves, tools, check=False):
    out = cut.cut(stock, cut.sweeps(moves, tools))
    if check:
        cut.rapid_hits(moves, tools, out)
    return out


def single(solid):
    solids = [s for s in solid.Solids() if abs(s.Volume()) > 1e-6]   # drop zero volume BOP debris
    if len(solids) != 1:
        raise RuntimeError(f"expected one solid, got {len(solids)}")
    if not solids[0].isValid():
        raise RuntimeError("machined solid is not valid")
    s = solids[0].clean()
    if not s.isValid():
        raise RuntimeError("cleaned solid is not valid")
    return s


def build(part, cnc, tools=None, lengths=None, axis="X", quirks=(), check=False):
    """the finished part, in its last setup's machine frame"""
    tools = tools or TOOLS
    lengths = lengths or LENGTH
    if part == "MNF-0610":
        op10, op20 = fanuc.run_part(cnc, [1610, 1620], lengths, quirks)
        p = single(machine(block(124.0, 84.0, 31.0), op10, tools, check))
        p = turn_over(p, axis)
        return single(machine(p, op20, tools, check))
    if part == "BRG-1140":
        (b,) = fanuc.run_part(cnc, [1140], lengths, quirks)
        return single(machine(block(90.0, 60.0, 40.0), b, tools, check))
    (c,) = fanuc.run_part(cnc, [2205], lengths, quirks)
    return single(machine(block(110.0, 45.0, 20.0), c, tools, check))


def crib(old_t6):
    tools, lengths = dict(TOOLS), dict(LENGTH)
    if old_t6:
        tools[6], lengths[6] = OLD_T6
    return tools, lengths

#!/usr/bin/env python3
"""Fanuc 0i-MF milling interpreter (the subset these programs use) -> tool tip moves in machine coords.

Reads the control backups: ALL-PROG.TXT (punch), CNC-PARA.TXT, TOOLOFST.TXT (memory C, G10 L10-13),
EXT_WKZ.TXT (G10 L2 P0-6). Executes custom macro B and emits every move of the tool tip as the
machine makes it.

Semantics followed (Fanuc 0i-MF operator/programming manual):
  * 3401#0 DPI = 0: an axis address written without a decimal point is in least input increment
    (0.001 mm). values coming from variables or [expressions] are taken as mm.
  * work coordinate = G54..G59 + EXT (P0) ; G52 sets (replaces) a local shift ; G10 L2 in G90
    overwrites the given axes only.
  * G43 Hn adds H geometry + H wear ; the tip ends at Zcmd + (Hn - real length of the loaded tool).
  * G41/G42 Dn use D geometry + D wear ; start-up / cancel type A (5003#0 SUP = 0).
  * I/J are always incremental from the arc start ; R < 0 -> arc over 180 deg.
  * G51.1 mirror: the path is mirrored, so arc direction and offset side reverse.
  * G68 rotates programmed coordinates (incremental ones too) about the given centre.
  * canned cycles: G91 R is from the initial level, Z from the R point, K repeats.
  * M98 runs in the caller's local variable level, G65 opens a new one with arguments.
  * a vacant variable in an address omits that address.
  * modal state (G90/G91, G52, cycle data ...) survives M99.
"""
import math
import re

AXIS_SCALED = set("XYZIJRQ")    # addresses that read 1 = 0.001 mm without a decimal point (K here is a repeat count)
ARG_MAP = {"A": 1, "B": 2, "C": 3, "I": 4, "J": 5, "K": 6, "D": 7, "E": 8, "F": 9, "H": 11,
           "M": 13, "Q": 17, "R": 18, "S": 19, "T": 20, "U": 21, "V": 22, "W": 23,
           "X": 24, "Y": 25, "Z": 26}
EPS = 1e-9


class NCError(Exception):
    pass


# ----------------------------------------------------------------------------------- backups
def read_params(path):
    p = {}
    for line in open(path):
        m = re.match(r"N(\d+)Q1(.*)", line.strip())
        if not m:
            continue
        p[int(m.group(1))] = m.group(2)
    return p


def param_bit(params, no, bit):
    v = params.get(no, "P00000000")
    m = re.match(r"P([01]{8})$", v)
    if not m:
        raise NCError(f"parameter {no} not bit type")
    return int(m.group(1)[7 - bit])


def read_g10(path):
    """returns list of dicts of the G10 lines"""
    out = []
    for line in open(path):
        line = line.strip()
        if not line.startswith("G10"):
            continue
        words = dict((a, float(v)) for a, v in re.findall(r"([A-Z])(-?[\d.]+)", line[3:]))
        out.append(words)
    return out


def read_offsets(path):
    off = {"Hg": {}, "Hw": {}, "Dg": {}, "Dw": {}}
    key = {10: "Hg", 11: "Hw", 12: "Dg", 13: "Dw"}
    for w in read_g10(path):
        off[key[int(w["L"])]][int(w["P"])] = w["R"]
    return off


def read_work(path):
    wk = {}
    for w in read_g10(path):
        wk[int(w["P"])] = [w.get("X", 0.0), w.get("Y", 0.0), w.get("Z", 0.0)]
    return wk


# ----------------------------------------------------------------------------------- program store
def load_programs(path):
    text = open(path).read().replace("%", "")
    progs, cur = {}, None
    for raw in text.splitlines():
        line = re.sub(r"\([^)]*\)", "", raw).strip().upper()
        m = re.match(r"^O(\d+)", line)
        if m:
            cur = int(m.group(1))
            progs[cur] = []
            line = line[m.end():].strip()
        if cur is None or not line:
            continue
        progs[cur].append(line)
    return progs


# ----------------------------------------------------------------------------------- expressions
TOK = re.compile(r"\s*(?:(\d+\.\d*|\.\d+|\d+)|(EQ|NE|GT|GE|LT|LE|AND|OR|XOR|MOD|SIN|COS|TAN|ATAN|SQRT|ABS|"
                 r"ROUND|FIX|FUP)|([#\[\]+\-*/]))")


def tokenize(s):
    out, i = [], 0
    s = s.strip()
    while i < len(s):
        m = TOK.match(s, i)
        if not m or m.end() == i:
            raise NCError(f"cannot tokenize {s[i:]!r}")
        out.append(m.group(1) or m.group(2) or m.group(3))
        i = m.end()
        while i < len(s) and s[i] == " ":
            i += 1
    return out


class Expr:
    def __init__(self, interp, toks):
        self.I, self.t, self.i = interp, toks, 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None

    def take(self, want=None):
        tok = self.peek()
        if want is not None and tok != want:
            raise NCError(f"expected {want} got {tok} in {' '.join(self.t)}")
        self.i += 1
        return tok

    def cond(self):
        a = self.expr()
        op = self.peek()
        if op in ("EQ", "NE", "GT", "GE", "LT", "LE"):
            self.take()
            b = self.expr()
            if op in ("EQ", "NE"):
                if a is None or b is None:
                    r = (a is None and b is None)
                else:
                    r = abs(a - b) < 1e-9
                return r if op == "EQ" else not r
            a = 0.0 if a is None else a
            b = 0.0 if b is None else b
            return {"GT": a > b, "GE": a >= b, "LT": a < b, "LE": a <= b}[op]
        return a

    def expr(self):
        v = self.term()
        while self.peek() in ("+", "-", "OR", "XOR"):
            op = self.take()
            w = self.term()
            v, w = (v or 0.0), (w or 0.0)
            v = v + w if op == "+" else v - w if op == "-" else float(int(v) | int(w)) if op == "OR" \
                else float(int(v) ^ int(w))
        return v

    def term(self):
        v = self.factor()
        while self.peek() in ("*", "/", "AND", "MOD"):
            op = self.take()
            w = self.factor()
            v, w = (v or 0.0), (w or 0.0)
            if op == "*":
                v = v * w
            elif op == "/":
                v = v / w
            elif op == "AND":
                v = float(int(v) & int(w))
            else:
                v = math.fmod(v, w)
        return v

    def factor(self):
        tok = self.peek()
        if tok == "-":
            self.take()
            v = self.factor()
            return None if v is None else -v
        if tok == "+":
            self.take()
            return self.factor()
        if tok == "[":
            self.take()
            v = self.expr()
            self.take("]")
            return v
        if tok == "#":
            self.take()
            n = self.factor()
            return self.I.getvar(int(round(n)))
        if tok in ("SIN", "COS", "TAN", "SQRT", "ABS", "ROUND", "FIX", "FUP", "ATAN"):
            self.take()
            self.take("[")
            v = self.expr() or 0.0
            self.take("]")
            if tok == "SIN":
                return math.sin(math.radians(v))
            if tok == "COS":
                return math.cos(math.radians(v))
            if tok == "TAN":
                return math.tan(math.radians(v))
            if tok == "SQRT":
                return math.sqrt(v)
            if tok == "ABS":
                return abs(v)
            if tok == "ROUND":
                return math.floor(abs(v) + 0.5) * (1 if v >= 0 else -1)
            if tok == "FIX":
                return float(math.trunc(v))
            if tok == "FUP":
                return float(math.trunc(v) + (0 if v == math.trunc(v) else (1 if v > 0 else -1)))
            raise NCError("ATAN not supported")
        if tok is None:
            raise NCError("unexpected end of expression")
        self.take()
        return float(tok)


# ----------------------------------------------------------------------------------- geometry helpers
def rot(v, deg):
    a = math.radians(deg)
    return (v[0] * math.cos(a) - v[1] * math.sin(a), v[0] * math.sin(a) + v[1] * math.cos(a))


def arc_center(p0, p1, r, ccw):
    """centre of the arc p0->p1 with radius R (negative: more than 180 deg)"""
    dx, dy = p1[0] - p0[0], p1[1] - p0[1]
    d = math.hypot(dx, dy)
    rr = abs(r)
    if d > 2 * rr + 1e-6:
        raise NCError("arc radius too small")
    h = math.sqrt(max(rr * rr - d * d / 4, 0.0))
    mx, my = (p0[0] + p1[0]) / 2, (p0[1] + p1[1]) / 2
    nx, ny = -dy / d, dx / d          # left normal of chord
    # minor arc ccw -> centre on the left of the chord
    side = 1 if ccw else -1
    if r < 0:
        side = -side
    return (mx + side * h * nx, my + side * h * ny)


class Seg:
    """planar XY path element in program coordinates at height z"""

    def __init__(self, kind, p0, p1, z, center=None, ccw=None):
        self.kind, self.p0, self.p1, self.z, self.c, self.ccw = kind, p0, p1, z, center, ccw

    def radius(self):
        return math.hypot(self.p0[0] - self.c[0], self.p0[1] - self.c[1])

    def tangent(self, at_end):
        if self.kind == "L":
            dx, dy = self.p1[0] - self.p0[0], self.p1[1] - self.p0[1]
            n = math.hypot(dx, dy)
            return (dx / n, dy / n)
        p = self.p1 if at_end else self.p0
        rx, ry = p[0] - self.c[0], p[1] - self.c[1]
        n = math.hypot(rx, ry)
        return (-ry / n, rx / n) if self.ccw else (ry / n, -rx / n)


def left(t):
    return (-t[1], t[0])


def offset_seg(s, d, side):
    """offset a segment by d to the left (side=+1) or right (side=-1)"""
    if s.kind == "L":
        n = left(s.tangent(False))
        o = (n[0] * d * side, n[1] * d * side)
        return Seg("L", (s.p0[0] + o[0], s.p0[1] + o[1]), (s.p1[0] + o[0], s.p1[1] + o[1]), s.z)
    r = s.radius()
    # left of a ccw arc is the inside
    inward = (1 if s.ccw else -1) * side
    nr = r - inward * d
    if nr <= 1e-9:
        raise NCError("offset arc radius not positive (interference)")
    def mv(p):
        rx, ry = p[0] - s.c[0], p[1] - s.c[1]
        k = nr / math.hypot(rx, ry)
        return (s.c[0] + rx * k, s.c[1] + ry * k)
    return Seg("A", mv(s.p0), mv(s.p1), s.z, s.c, s.ccw)


def intersect(a, b, near):
    """intersection of offset elements a and b (as infinite line / full circle) nearest to `near`"""
    pts = []
    if a.kind == "L" and b.kind == "L":
        d1 = (a.p1[0] - a.p0[0], a.p1[1] - a.p0[1])
        d2 = (b.p1[0] - b.p0[0], b.p1[1] - b.p0[1])
        den = d1[0] * d2[1] - d1[1] * d2[0]
        if abs(den) < 1e-12:
            return None
        t = ((b.p0[0] - a.p0[0]) * d2[1] - (b.p0[1] - a.p0[1]) * d2[0]) / den
        return (a.p0[0] + t * d1[0], a.p0[1] + t * d1[1])
    if a.kind == "A" and b.kind == "A":
        c1, r1, c2, r2 = a.c, a.radius(), b.c, b.radius()
        dx, dy = c2[0] - c1[0], c2[1] - c1[1]
        d = math.hypot(dx, dy)
        if d < 1e-12:
            return None
        x = (d * d + r1 * r1 - r2 * r2) / (2 * d)
        h2 = r1 * r1 - x * x
        if h2 < -1e-9:
            return None
        h = math.sqrt(max(h2, 0))
        bx, by = c1[0] + x * dx / d, c1[1] + x * dy / d
        pts = [(bx - h * dy / d, by + h * dx / d), (bx + h * dy / d, by - h * dx / d)]
    else:
        ln, ar = (a, b) if a.kind == "L" else (b, a)
        d = (ln.p1[0] - ln.p0[0], ln.p1[1] - ln.p0[1])
        n = math.hypot(*d)
        d = (d[0] / n, d[1] / n)
        f = (ln.p0[0] - ar.c[0], ln.p0[1] - ar.c[1])
        bq = f[0] * d[0] + f[1] * d[1]
        cq = f[0] ** 2 + f[1] ** 2 - ar.radius() ** 2
        disc = bq * bq - cq
        if disc < -1e-9:
            return None
        sq = math.sqrt(max(disc, 0))
        pts = [(ln.p0[0] + (-bq + s) * d[0], ln.p0[1] + (-bq + s) * d[1]) for s in (sq, -sq)]
    return min(pts, key=lambda p: math.hypot(p[0] - near[0], p[1] - near[1]))


def comp_path(start, segs, end, d, side):
    """type A start-up / cancel cutter compensation. returns list of Seg for the tool centre."""
    if d < 1e-12:
        out, cur = [], start
        for s in segs:
            out.append(s)
        return [Seg("L", start, segs[0].p0, segs[0].z)] + out + [Seg("L", segs[-1].p1, end, segs[-1].z)]
    offs = [offset_seg(s, d, side) for s in segs]
    # junctions
    pts_start = [o.p0 for o in offs]
    pts_end = [o.p1 for o in offs]
    path = []
    out_segs = [Seg(o.kind, o.p0, o.p1, o.z, o.c, o.ccw) for o in offs]
    inserts = {}
    for k in range(len(segs) - 1):
        t1 = segs[k].tangent(True)
        t2 = segs[k + 1].tangent(False)
        cross = t1[0] * t2[1] - t1[1] * t2[0]
        dot = t1[0] * t2[0] + t1[1] * t2[1]
        if abs(cross) < 1e-9 and dot > 0:
            continue                                   # tangent, offsets meet
        inner = cross * side > 0
        if inner:
            p = intersect(out_segs[k], out_segs[k + 1], segs[k].p1)
            if p is None:
                raise NCError("no intersection at inner corner")
            out_segs[k].p1 = p
            out_segs[k + 1].p0 = p
        else:
            corner = segs[k].p1
            inserts[k] = Seg("A", out_segs[k].p1, out_segs[k + 1].p0, segs[k].z, corner, side < 0)
    for k, s in enumerate(out_segs):
        path.append(s)
        if k in inserts:
            path.append(inserts[k])
    path.insert(0, Seg("L", start, out_segs[0].p0, segs[0].z))
    path.append(Seg("L", out_segs[-1].p1, end, segs[-1].z))
    return path


# ----------------------------------------------------------------------------------- interpreter
class Machine:
    def __init__(self, progs, params, offsets, work, tool_len, quirks=()):
        self.progs = progs
        self.quirks = set(quirks)     # wrong readings, used only by the dev misread battery
        self.dpi = 1 if "dpi1" in self.quirks else param_bit(params, 3401, 0)
        if param_bit(params, 5003, 0) != 0:
            raise NCError("only start-up type A modelled")
        self.off, self.work, self.tool_len = offsets, work, tool_len
        self.common = {}
        self.moves = []          # (kind, tool, p0, p1, arc) machine coords of tool tip
        self.reset()

    def reset(self):
        self.locals = [dict()]
        self.g90 = True
        self.motion = 0
        self.wcs = 1
        self.local_shift = (0.0, 0.0)
        self.rot = None                  # (cx, cy, deg)
        self.mirror = [None, None]       # mirror axis value for X, Y
        self.h = None                    # H number
        self.tool = None
        self.next_tool = None
        self.pos = None                  # program coords [x, y, z] in current frame
        self.mpos = None                 # machine tip coords
        self.comp = None                 # (side, d, start_point, segs)
        self.cycle = None
        self.retract_init = True

    # variables
    def getvar(self, n):
        if n == 0:
            return None
        if 1 <= n <= 33:
            return self.locals[-1].get(n)
        if 100 <= n <= 199 or 500 <= n <= 999:
            return self.common.get(n)
        for base, key in ((10000, "Hw"), (11000, "Hg"), (12000, "Dw"), (13000, "Dg")):
            if base < n <= base + 400:
                return self.off[key].get(n - base, 0.0)
        raise NCError(f"variable #{n} not supported")

    def setvar(self, n, v):
        if 1 <= n <= 33:
            self.locals[-1][n] = v
        elif 100 <= n <= 199 or 500 <= n <= 999:
            self.common[n] = v
        else:
            raise NCError(f"cannot write #{n}")

    def ev(self, s):
        e = Expr(self, tokenize(s))
        v = e.expr()
        if e.i != len(e.t):
            raise NCError(f"trailing tokens in {s}")
        return v

    def evcond(self, s):
        s = s.strip()
        if s.startswith("[") and s.endswith("]"):
            s = s[1:-1]
        e = Expr(self, tokenize(s))
        v = e.cond()
        if e.i != len(e.t):
            raise NCError(f"trailing tokens in {s}")
        return v

    # frames
    def to_machine(self, p):
        x, y, z = p
        if self.mirror[0] is not None:
            x = 2 * self.mirror[0] - x
        if self.mirror[1] is not None:
            y = 2 * self.mirror[1] - y
        if self.rot is not None:
            cx, cy, a = self.rot
            v = rot((x - cx, y - cy), a)
            x, y = cx + v[0], cy + v[1]
        w, e = self.work[self.wcs], self.work[0]
        if "no_ext" in self.quirks:
            e = [0.0, 0.0, 0.0]
        hv = self.hval() if self.h else None
        if hv is None:
            raise NCError("Z move without tool length offset")
        L = self.tool_len[self.tool]
        return (x + self.local_shift[0] + w[0] + e[0],
                y + self.local_shift[1] + w[1] + e[1],
                z + w[2] + e[2] + hv - L)

    def hval(self):
        h = self.tool if "h_is_tool" in self.quirks else self.h
        hw = 0.0 if "no_hwear" in self.quirks else self.off["Hw"].get(h, 0.0)
        return self.off["Hg"].get(h, 0.0) + hw

    def from_machine(self, m):
        w, e = self.work[self.wcs], self.work[0]
        if "no_ext" in self.quirks:
            e = [0.0, 0.0, 0.0]
        hv = self.hval()
        L = self.tool_len[self.tool]
        x = m[0] - self.local_shift[0] - w[0] - e[0]
        y = m[1] - self.local_shift[1] - w[1] - e[1]
        z = m[2] - w[2] - e[2] - hv + L
        if self.rot is not None:
            cx, cy, a = self.rot
            v = rot((x - cx, y - cy), -a)
            x, y = cx + v[0], cy + v[1]
        if self.mirror[0] is not None:
            x = 2 * self.mirror[0] - x
        if self.mirror[1] is not None:
            y = 2 * self.mirror[1] - y
        return [x, y, z]

    def refresh(self):
        """frame changed: the tool stays put, its programmed position is re-expressed"""
        if self.mpos is not None and self.pos is not None and None not in self.pos:
            self.pos = self.from_machine(self.mpos)

    def mirrored_odd(self):
        return (self.mirror[0] is not None) != (self.mirror[1] is not None)

    def emit(self, kind, p_new, arc=None):
        m_new = self.to_machine(p_new)
        if self.mpos is not None:
            a = None
            if arc is not None:
                c, ccw = arc
                cm = self.to_machine((c[0], c[1], p_new[2]))
                flip = self.mirrored_odd() and "mirror_keeps_arcs" not in self.quirks
                a = ((cm[0], cm[1]), ccw != flip)
            self.moves.append((kind, self.tool, self.mpos, m_new, a))
        self.mpos = m_new
        self.pos = list(p_new)

    # word parsing
    def words(self, line):
        out = []
        i = 0
        while i < len(line):
            c = line[i]
            if c == " ":
                i += 1
                continue
            if not c.isalpha():
                raise NCError(f"bad block {line!r}")
            i += 1
            j = i
            if j < len(line) and line[j] in "-+":
                j += 1
            if j < len(line) and line[j] == "[":
                depth = 0
                while True:
                    if line[j] == "[":
                        depth += 1
                    elif line[j] == "]":
                        depth -= 1
                        if depth == 0:
                            j += 1
                            break
                    j += 1
                raw = line[i:j]
                out.append((c, raw, "expr"))
            elif j < len(line) and line[j] == "#":
                j += 1
                if line[j] == "[":
                    depth = 0
                    while True:
                        if line[j] == "[":
                            depth += 1
                        elif line[j] == "]":
                            depth -= 1
                            if depth == 0:
                                j += 1
                                break
                        j += 1
                else:
                    while j < len(line) and line[j].isdigit():
                        j += 1
                out.append((c, line[i:j], "expr"))
            else:
                while j < len(line) and (line[j].isdigit() or line[j] == "."):
                    j += 1
                out.append((c, line[i:j], "num"))
            i = j
        return out

    def value(self, addr, raw, kind):
        if kind == "expr":
            return self.ev(raw)
        v = float(raw)
        if addr in AXIS_SCALED and "." not in raw and self.dpi == 0:
            v *= 0.001
        return v

    # ------------------------------------------------------------------ run
    def run(self, prog):
        stack = []          # (prog, pc, is_g65)
        cur, pc = prog, 0
        loops = {}
        steps = 0
        while True:
            steps += 1
            if steps > 200000:
                raise NCError("runaway")
            lines = self.progs[cur]
            if pc >= len(lines):
                raise NCError(f"fell off O{cur}")
            line = lines[pc]
            pc += 1
            m = re.match(r"^N(\d+)\s*", line)
            if m:
                line = line[m.end():]
            if not line:
                continue
            # ---------------- macro statements
            if line.startswith("#"):
                lhs, rhs = line.split("=", 1)
                n = int(round(self.ev(lhs[1:]))) if lhs[1] == "[" else int(lhs[1:])
                self.setvar(n, self.ev(rhs))
                continue
            if line.startswith("IF"):
                m = re.match(r"IF\s*(\[.*\])\s*GOTO\s*(\d+)$", line)
                if m:
                    if self.evcond(m.group(1)):
                        pc = self.find_label(cur, int(m.group(2)))
                    continue
                m = re.match(r"IF\s*(\[.*\])\s*THEN\s*#(\d+)\s*=(.*)$", line)
                if m:
                    if self.evcond(m.group(1)):
                        self.setvar(int(m.group(2)), self.ev(m.group(3)))
                    continue
                raise NCError(f"bad IF {line}")
            if line.startswith("GOTO"):
                pc = self.find_label(cur, int(line[4:]))
                continue
            if line.startswith("WHILE"):
                m = re.match(r"WHILE\s*(\[.*\])\s*DO(\d)$", line)
                if not self.evcond(m.group(1)):
                    pc = self.find_end(cur, pc, m.group(2))
                continue
            m = re.match(r"^END(\d)$", line)
            if m:
                pc = self.find_while(cur, pc - 1, m.group(1))
                continue
            # ---------------- NC block
            ws = self.words(line)
            gs = [self.value(a, r, k) for a, r, k in ws if a == "G"]
            mcodes = [int(self.value(a, r, k)) for a, r, k in ws if a == "M"]
            vals = {}
            for a, r, k in ws:
                if a in "GMN":
                    continue
                v = self.value(a, r, k)
                if v is None and "vacant_is_zero" in self.quirks:
                    v = 0.0
                if v is None:
                    continue      # vacant variable: address omitted
                vals[a] = v
            if 65 in [int(g) for g in gs]:
                for a, r, k in ws:
                    if a not in "GP" and k == "num" and "." not in r:
                        raise NCError(f"G65 argument without decimal point: {line}")
                args = {}
                for a, v in vals.items():
                    if a == "P":
                        continue
                    args[ARG_MAP[a]] = v
                stack.append((cur, pc, True))
                self.locals.append(args)
                cur, pc = int(vals["P"]), 0
                continue
            if 98 in mcodes:
                own = "m98_new_level" in self.quirks
                stack.append((cur, pc, own))
                if own:
                    self.locals.append(dict(self.locals[-1]))
                cur, pc = int(vals["P"]), 0
                continue
            if 99 in mcodes:
                cur, pc, g65 = stack.pop()
                if g65:
                    self.locals.pop()
                if "m99_restores_g90" in self.quirks:
                    self.g90 = True
                continue
            if 30 in mcodes:
                if self.comp:
                    raise NCError("M30 in compensation")
                return
            self.block(gs, mcodes, vals, line)

    def find_label(self, prog, n):
        for i, l in enumerate(self.progs[prog]):
            if re.match(rf"^N0*{n}(?!\d)", l):
                return i
        raise NCError(f"N{n} not found in O{prog}")

    def find_end(self, prog, pc, k):
        for i in range(pc, len(self.progs[prog])):
            if re.match(rf"^(N\d+\s*)?END{k}$", self.progs[prog][i]):
                return i + 1
        raise NCError("END not found")

    def find_while(self, prog, pc, k):
        for i in range(pc, -1, -1):
            if re.search(rf"DO{k}$", self.progs[prog][i]):
                return i
        raise NCError("WHILE not found")

    # ------------------------------------------------------------------ one NC block
    def block(self, gs, mcodes, vals, line):
        gi = [round(g, 1) for g in gs]
        one_shot = None
        new_comp = None
        for g in gi:
            if g in (0, 1, 2, 3):
                self.motion = int(g)
                self.cycle = None if self.cycle is None else self.cycle
                if self.cycle is not None:
                    self.cycle = None
            elif g == 90:
                self.g90 = True
            elif g == 91:
                self.g90 = False
            elif g in (54, 55, 56, 57, 58, 59):
                self.wcs = int(g) - 53
            elif g in (17, 21, 94, 49, 69):
                if g == 49:
                    self.h = None
                if g == 69:
                    self.rot = None
                    self.refresh()
            elif g == 40:
                new_comp = 40
            elif g in (41, 42):
                new_comp = int(g)
            elif g == 43:
                self.h = int(vals["H"])
            elif g in (10, 28, 52, 68):
                one_shot = int(g)
            elif g == 51.1:
                one_shot = 51.1
            elif g == 50.1:
                one_shot = 50.1
            elif g == 80:
                self.cycle = None
                self.motion = 0 if self.motion >= 80 else self.motion
            elif g in (81, 82, 83, 73, 85):
                self.motion = int(g)
                self.cycle = {"init": None}
            elif g == 98:
                self.retract_init = True
            elif g == 99:
                self.retract_init = False
            else:
                raise NCError(f"G{g} not modelled ({line})")
        if "T" in vals:
            self.next_tool = int(vals["T"])
        if 6 in mcodes:
            self.tool = int(self.next_tool)
        if one_shot == 10:
            if "no_g10" in self.quirks:
                return
            p = int(vals["P"])
            if int(vals["L"]) != 2:
                raise NCError("G10 only L2")
            for k, a in enumerate("XYZ"):
                if a in vals:
                    self.work[p][k] = vals[a] if self.g90 else self.work[p][k] + vals[a]
            return
        if one_shot == 52:
            if not self.g90:
                raise NCError("G91 G52 not modelled")
            nx, ny = vals.get("X", self.local_shift[0]), vals.get("Y", self.local_shift[1])
            if "g52_adds" in self.quirks:
                nx, ny = self.local_shift[0] + nx, self.local_shift[1] + ny
            self.local_shift = (nx, ny)
            if "Z" in vals:
                raise NCError("G52 Z not modelled")
            self.refresh()
            return
        if one_shot == 68:
            if not self.g90:
                raise NCError("G68 in G91 not modelled")
            self.rot = None if "no_g68" in self.quirks else (vals["X"], vals["Y"], vals["R"])
            self.refresh()
            return
        if one_shot == 51.1:
            if "X" in vals:
                self.mirror[0] = vals["X"]
            if "Y" in vals:
                self.mirror[1] = vals["Y"]
            self.refresh()
            return
        if one_shot == 50.1:
            if "X" in vals:
                self.mirror[0] = None
            if "Y" in vals:
                self.mirror[1] = None
            self.refresh()
            return
        if one_shot == 28:
            if self.g90 or set(vals) - {"Z"} or vals.get("Z") != 0:
                raise NCError("only G91 G28 Z0 modelled")
            if self.mpos is not None:
                top = (self.mpos[0], self.mpos[1], 0.0 - self.tool_len[self.tool])
                self.moves.append(("rapid", self.tool, self.mpos, top, None))
            self.mpos = None
            self.pos = None
            return
        if self.motion >= 80 and self.cycle is not None:
            self.do_cycle(vals)
            return
        axes = [a for a in "XYZ" if a in vals]
        if not axes and self.motion not in (2, 3) and new_comp is None:
            return
        if not axes and self.motion in (2, 3) and not ("I" in vals or "J" in vals or "R" in vals):
            return
        if self.pos is None:
            # first positioning after a tool change: needs absolute X Y then Z with G43
            if not self.g90:
                raise NCError("incremental move from unknown position")
            self.pos = [vals.get("X"), vals.get("Y"), vals.get("Z")]
            if self.pos[2] is None:
                return
            if None in self.pos:
                raise NCError("unknown position")
            self.mpos = self.to_machine(self.pos)
            return
        if None in self.pos:
            if "Z" in vals and self.g90:
                self.pos[2] = vals["Z"]
                if "X" in vals:
                    self.pos[0] = vals["X"]
                if "Y" in vals:
                    self.pos[1] = vals["Y"]
                if None in self.pos:
                    raise NCError("unknown position")
                self.mpos = self.to_machine(self.pos)
                return
            raise NCError("unknown position")
        tgt = list(self.pos)
        for k, a in enumerate("XYZ"):
            if a in vals:
                tgt[k] = vals[a] if self.g90 else self.pos[k] + vals[a]
        kind = "rapid" if self.motion == 0 else "feed"
        arc = None
        if self.motion in (2, 3):
            ccw = self.motion == 3
            if "R" in vals:
                c = arc_center(self.pos, tgt, vals["R"], ccw)
            else:
                c = (self.pos[0] + vals.get("I", 0.0), self.pos[1] + vals.get("J", 0.0))
            if abs(tgt[2] - self.pos[2]) > 1e-9:
                raise NCError("helical not modelled")
            arc = (c, ccw)
        # cutter compensation
        if new_comp in (41, 42):
            if self.motion not in (0, 1) or abs(tgt[2] - self.pos[2]) > 1e-9:
                raise NCError("start-up must be a linear XY move")
            dn = int(vals["D"])
            d = self.off["Dg"].get(dn, 0.0) + (0.0 if "no_dwear" in self.quirks else self.off["Dw"].get(dn, 0.0))
            self.comp = {"side": 1 if new_comp == 41 else -1, "d": d, "start": tuple(self.pos),
                         "segs": [Seg("L", tuple(self.pos[:2]), tuple(tgt[:2]), tgt[2])], "kind": kind}
            self.pos = tgt
            return
        if self.comp is not None and new_comp != 40:
            if abs(tgt[2] - self.pos[2]) > 1e-9:
                raise NCError("Z move inside compensation")
            if arc is None:
                s = Seg("L", tuple(self.pos[:2]), tuple(tgt[:2]), tgt[2])
            else:
                s = Seg("A", tuple(self.pos[:2]), tuple(tgt[:2]), tgt[2], arc[0], arc[1])
            self.comp["segs"].append(s)
            self.pos = tgt
            return
        if new_comp == 40 and self.comp is not None:
            if arc is not None or abs(tgt[2] - self.pos[2]) > 1e-9:
                raise NCError("cancel must be linear XY")
            c = self.comp
            segs = c["segs"]
            startup = segs[0]
            body = segs[1:]
            path = comp_path(startup.p0, body, tuple(tgt[:2]), c["d"], c["side"])
            z = tgt[2]
            p = list(self.pos)
            # the tool is still at the start-up point (uncompensated) in machine terms
            self.pos = [startup.p0[0], startup.p0[1], z]
            self.mpos = self.to_machine(self.pos)
            for s in path:
                if math.hypot(s.p1[0] - s.p0[0], s.p1[1] - s.p0[1]) < 1e-9 and s.kind == "L":
                    continue
                self.emit("feed", [s.p1[0], s.p1[1], z], None if s.kind == "L" else (s.c, s.ccw))
            self.comp = None
            self.pos = tgt
            return
        self.emit(kind, tgt, arc)

    def do_cycle(self, vals):
        c = self.cycle
        for a in "RZQF":
            if a in vals:
                c[a] = vals[a]
        if "X" not in vals and "Y" not in vals and "K" not in vals and c.get("done"):
            return
        if c["init"] is None:
            c["init"] = self.pos[2]
        reps = int(vals.get("K", 1))
        for _ in range(reps):
            tgt = list(self.pos)
            for k, a in enumerate("XY"):
                if a in vals:
                    tgt[k] = vals[a] if self.g90 else self.pos[k] + vals[a]
            if self.g90:
                rz, bz = c["R"], c["Z"]
            elif "g91_z_from_init" in self.quirks:
                rz = c["init"] + c["R"]
                bz = c["init"] + c["Z"]
            else:
                rz = c["init"] + c["R"]
                bz = rz + c["Z"]
            self.emit("rapid", [tgt[0], tgt[1], self.pos[2]])
            self.emit("rapid", [tgt[0], tgt[1], rz])
            self.emit("feed", [tgt[0], tgt[1], bz])
            self.emit("rapid", [tgt[0], tgt[1], c["init"] if self.retract_init else rz])
            c["done"] = True


def run_part(cncdir, progs_to_run, tool_len, quirks=()):
    """run each program in order on a fresh control state (program state resets at M30,
    the offset memory does not). returns the list of move lists, one per program"""
    if isinstance(cncdir, dict):          # an in-memory control state (see history.load_state)
        progs, params = cncdir["progs"], cncdir["params"]
        off = cncdir["off"]
        work = {k: list(v) for k, v in cncdir["work"].items()}
    else:
        progs = load_programs(f"{cncdir}/ALL-PROG.TXT")
        params = read_params(f"{cncdir}/CNC-PARA.TXT")
        off = read_offsets(f"{cncdir}/TOOLOFST.TXT")
        work = read_work(f"{cncdir}/EXT_WKZ.TXT")
    out = []
    for o in progs_to_run:
        m = Machine(progs, params, off, work, tool_len, quirks)
        m.run(o)
        out.append(m.moves)
        work = m.work
    return out

#!/usr/bin/env python3
"""Material removal for the moves produced by fanuc.py, exact B-rep in CadQuery 2.8 / OCCT.

Every tool is a solid of revolution about Z with radius rho(h) at height h above the tip. Feed moves
are either pure Z (plunge: the tool at the low point, with its shank) or horizontal lines and arcs.
For a horizontal move the swept volume is exact:
  line : prism of the cross section {|u| <= rho(h)} along the segment, plus the tool at each end
  arc  : revolve of {|r - Rp| <= rho(h)} about the arc axis over the arc, plus the tool at each end
"""
import math

import cadquery as cq
from OCP.BRepAlgoAPI import BRepAlgoAPI_Cut, BRepAlgoAPI_Common
from OCP.TopTools import TopTools_ListOfShape

SHANK = 160.0
FUZZY = 1e-5          # sweeps that graze the same wall meet tangentially


class Tool:
    def __init__(self, kind, dia, corner=0.0, point=None, tip_flat=0.0):
        self.kind, self.R, self.rc, self.point, self.r0 = kind, dia / 2, corner, point, tip_flat / 2

    def half_profile(self, w):
        """closed outline in (u, h), u >= 0 half, drawn on workplane w (u -> x, h -> y)"""
        R, H = self.R, SHANK
        if self.kind == "flat":
            return w.moveTo(0, 0).lineTo(R, 0).lineTo(R, H).lineTo(0, H).close()
        if self.kind == "bull":
            pts = [(0, 0)] + self.corner_pts(0.0) + [(R, H), (0, H)]
            w = w.moveTo(*pts[0])
            for p in pts[1:]:
                w = w.lineTo(*p)
            return w.close()
        if self.kind == "cone":
            hc = (R - self.r0) / math.tan(math.radians(self.point / 2))
            w = w.moveTo(0, 0)
            if self.r0 > 0:
                w = w.lineTo(self.r0, 0)
            return w.lineTo(R, hc).lineTo(R, H).lineTo(0, H).close()
        raise ValueError(self.kind)

    def corner_pts(self, shift):
        """bull nose corner radius as a 24 segment polyline, sagitta 5e-4 mm at R1. torus against
        torus tangencies between neighbouring sweeps defeat the OCCT booleans; planes and cones
        do not, and 5e-4 mm is 40 times under the 0.02 mm the models are held to"""
        R, rc, n = self.R, self.rc, 24
        return [(shift + R - rc + rc * math.sin(math.pi / 2 * k / n), rc - rc * math.cos(math.pi / 2 * k / n))
                for k in range(n + 1)]

    def section(self, w, shift, poly=True):
        """full cross section {shift - rho(h) <= u <= shift + rho(h)}"""
        R, H = self.R, SHANK
        if self.kind == "flat":
            return (w.moveTo(shift - R, 0).lineTo(shift + R, 0).lineTo(shift + R, H)
                    .lineTo(shift - R, H).close())
        if self.kind == "bull" and poly:
            rc, n = self.rc, 24
            right = self.corner_pts(shift)
            left = [(2 * shift - u, h) for u, h in reversed(right)]
            pts = right + [(shift + R, H), (shift - R, H)] + left
            w = w.moveTo(*pts[0])
            for p in pts[1:]:
                w = w.lineTo(*p)
            return w.close()
        if self.kind == "bull":
            rc = self.rc
            return (w.moveTo(shift - R + rc, 0).lineTo(shift + R - rc, 0)
                    .radiusArc((shift + R, rc), -rc).lineTo(shift + R, H).lineTo(shift - R, H)
                    .lineTo(shift - R, rc).radiusArc((shift - R + rc, 0), -rc).close())
        if self.kind == "cone":
            hc = (R - self.r0) / math.tan(math.radians(self.point / 2))
            pts = [(shift - self.r0, 0)]
            if self.r0 > 0:
                pts.append((shift + self.r0, 0))
            pts += [(shift + R, hc), (shift + R, H), (shift - R, H), (shift - R, hc)]
            w = w.moveTo(*pts[0])
            for p in pts[1:]:
                w = w.lineTo(*p)
            return w.close()
        raise ValueError(self.kind)

    def at(self, p):
        wp = cq.Workplane(cq.Plane(origin=p, xDir=(1, 0, 0), normal=(0, -1, 0)))
        return self.half_profile(wp).revolve(360, (0, 0, 0), (0, 1, 0)).val()

    def line(self, p0, p1):
        d = (p1[0] - p0[0], p1[1] - p0[1])
        L = math.hypot(*d)
        d = (d[0] / L, d[1] / L)
        n = (-d[1], d[0], 0)
        wp = cq.Workplane(cq.Plane(origin=p0, xDir=n, normal=(d[0], d[1], 0)))
        return self.section(wp, 0.0).extrude(L).val()

    def arc(self, p0, p1, c, ccw):
        if not ccw:
            p0, p1 = p1, p0
        a0 = math.atan2(p0[1] - c[1], p0[0] - c[0])
        a1 = math.atan2(p1[1] - c[1], p1[0] - c[0])
        sweep = math.degrees(a1 - a0) % 360.0
        if sweep < 1e-7:
            sweep = 360.0
        Rp = math.hypot(p0[0] - c[0], p0[1] - c[1])
        e1 = ((p0[0] - c[0]) / Rp, (p0[1] - c[1]) / Rp, 0)
        # local y must be +Z: normal x xDir = Z  ->  normal = (e1y, -e1x, 0)
        plane = cq.Plane(origin=(c[0], c[1], p0[2]), xDir=e1, normal=(e1[1], -e1[0], 0))
        if abs(Rp - self.R) < 1e-9:
            Rp = self.R
        wire = self.section(cq.Workplane(plane), Rp).val()
        face = cq.Face.makeFromWires(wire)
        if Rp < self.R:
            # path circle smaller than the tool: everything from the axis out is swept inside the
            # sector (points outside it are covered by the tools at the two ends)
            w = Rp + self.R + 1
            keep = cq.Face.makeFromWires(cq.Workplane(plane).center(w / 2, SHANK / 2)
                                         .rect(w, SHANK + 2).val())
            face = face.intersect(keep)
            fs = face.Faces()
            if len(fs) != 1:
                raise RuntimeError("clipped section is not one face")
            face = fs[0]
        ax0 = cq.Vector(c[0], c[1], p0[2])
        return cq.Solid.revolve(face, sweep, ax0, ax0 + cq.Vector(0, 0, 1))


def sweeps(moves, tools, z_eps=1e-7):
    """solids swept by the feed moves (rapids are checked separately)"""
    out = []
    for kind, t, p0, p1, arc in moves:
        if kind != "feed":
            continue
        tool = tools[t]
        dz = p1[2] - p0[2]
        dxy = math.hypot(p1[0] - p0[0], p1[1] - p0[1])
        if arc is not None:
            out.append(tool.arc(p0, p1, arc[0], arc[1]))
            out.append(tool.at(p1))
        elif dxy < 1e-9:
            out.append(tool.at(p1 if dz < 0 else p0))
        elif abs(dz) < z_eps:
            out.append(tool.line(p0, p1))
            out.append(tool.at(p0))
            out.append(tool.at(p1))
        else:
            raise ValueError(f"feed move with both XY and Z: {p0} -> {p1}")
    bad = [k for k, x in enumerate(out) if not x.isValid()]
    if bad:
        raise RuntimeError(f"invalid swept solids: {bad}")
    return out


def cut_one(stock, tool):
    args, tl = TopTools_ListOfShape(), TopTools_ListOfShape()
    args.Append(stock.wrapped)
    tl.Append(tool.wrapped)
    op = BRepAlgoAPI_Cut()
    op.SetArguments(args)
    op.SetTools(tl)
    op.SetFuzzyValue(FUZZY)
    op.Build()
    if not op.IsDone():
        raise RuntimeError("boolean cut failed")
    return cq.Shape.cast(op.Shape())


def cut(stock, solids):
    """remove the swept solids one at a time. a single boolean with hundreds of overlapping
    tools mis-classifies whole pieces on these parts; one at a time stays exact and checkable"""
    part = stock
    for k, s in enumerate(solids):
        r = cut_one(part, s)
        pieces = [x for x in r.Solids() if abs(x.Volume()) > 1e-6]
        if len(pieces) != 1 or not pieces[0].isValid():
            raise RuntimeError(f"cut {k}: pieces {[round(x.Volume(), 4) for x in pieces]}, "
                               f"valid={[x.isValid() for x in pieces]}")
        part = pieces[0]
    return part


def overlap(a, b):
    op = BRepAlgoAPI_Common(a.wrapped, b.wrapped)
    return cq.Shape.cast(op.Shape()).Volume()


def rapid_hits(moves, tools, stock):
    """volume of finished material any rapid passes through (should be zero); straight
    retracts out of a cut are skipped"""
    worst = 0.0
    for kind, t, p0, p1, arc in moves:
        if kind != "rapid":
            continue
        if math.hypot(p1[0] - p0[0], p1[1] - p0[1]) < 1e-9 and p1[2] >= p0[2]:
            continue
        tool = tools[t]
        dz = p1[2] - p0[2]
        dxy = math.hypot(p1[0] - p0[0], p1[1] - p0[1])
        if dxy < 1e-9:
            s = [tool.at(p1 if dz < 0 else p0)]
        elif abs(dz) < 1e-7:
            s = [tool.line(p0, p1), tool.at(p0), tool.at(p1)]
        else:
            s = [tool.at(p0), tool.at(p1)]
            n = int(dxy) + 2
            for k in range(1, n):
                f = k / n
                s.append(tool.at(tuple(p0[i] + f * (p1[i] - p0[i]) for i in range(3))))
        for x in s:
            v = overlap(stock, x)
            if v > 1e-6:
                worst = max(worst, v)
                print("RAPID HIT", t, p0, p1, round(v, 4))
    return worst

